// Message timestamps are generated by the server, but the client's
// clock may disagree with the server's. We track that difference so
// that deadlines computed from message timestamps match the ones
// the server will actually enforce.

let clock_offset_seconds = 0;

// We record when a request started by both of the client's clocks,
// because Date.now() jumps when the system clock is changed, and
// performance.now() pauses while the device sleeps in some browsers.
export type RequestStart = {
    wall_ms: number;
    monotonic_ms: number;
};

export function get_request_start(): RequestStart {
    return {wall_ms: Date.now(), monotonic_ms: performance.now()};
}

export function update_offset(server_timestamp: number, request_start: RequestStart): void {
    // The server read its clock as `server_timestamp` sometime between
    // when the request started and now, which bounds the offset.
    const wall_now_ms = Date.now();
    const elapsed_ms = Math.max(
        wall_now_ms - request_start.wall_ms,
        performance.now() - request_start.monotonic_ms,
    );
    const min_offset_seconds = server_timestamp - wall_now_ms / 1000;
    const max_offset_seconds = min_offset_seconds + elapsed_ms / 1000;

    // Keep an estimate this sample agrees with, so that a client
    // clock that matches the server's isn't replaced by a guess that
    // can be off by up to half the request's duration.
    if (clock_offset_seconds < min_offset_seconds || clock_offset_seconds > max_offset_seconds) {
        clock_offset_seconds = (min_offset_seconds + max_offset_seconds) / 2;
    }
}

export function initialize(server_timestamp: number): void {
    // The server read its clock for the initial state data after
    // this page started loading, at performance.now() time 0. We
    // don't use performance.timeOrigin as the wall clock time of
    // that, since it drifts from Date.now() after the device sleeps.
    update_offset(server_timestamp, {
        wall_ms: Date.now() - performance.now(),
        monotonic_ms: 0,
    });
}

// In seconds, like message timestamps.
export function now(): number {
    return Date.now() / 1000 + clock_offset_seconds;
}

export function clear_for_testing(): void {
    clock_offset_seconds = 0;
}
